insert into public.content_pages (slug,title,excerpt,content,seo_title,seo_description,is_published,published_at)
values
('about','About Affinova','Learn what Affinova is and how it works.','<h2>About Affinova</h2><p>Affinova is a product discovery and recommendation website. We organize products, deals and buying guides so visitors can compare options and discover products more easily.</p><p>Affinova does not sell or ship the products listed on the site. Purchases are completed with the retailer or marketplace shown through a product link.</p>','About Affinova','Learn about Affinova, a product discovery and recommendation website.',true,now()),
('contact','Contact','Get in touch with Affinova.','<h2>Contact Affinova</h2><p>For general questions, corrections, partnership enquiries or content feedback, please use the contact details published in the site settings.</p><p>If no contact email is currently listed, the contact page will be updated when an official support address is configured.</p>','Contact Affinova','Contact Affinova for questions, corrections, partnerships and feedback.',true,now()),
('privacy','Privacy Policy','How Affinova handles website information.','<h2>Privacy Policy</h2><p>Affinova may collect basic technical and usage information needed to operate the website, measure traffic and improve the service. This can include pages viewed, device information, anonymous session identifiers, referral information and campaign parameters.</p><p>Affinova does not intentionally collect sensitive personal information through the public analytics system. Affiliate clicks and product interactions may be recorded in anonymous analytics.</p><p>Third-party retailers and affiliate networks may have their own privacy policies when you leave Affinova and visit their websites.</p>','Privacy Policy | Affinova','Read the Affinova privacy policy and learn how website analytics and affiliate interactions are handled.',true,now()),
('terms','Terms of Use','Terms for using the Affinova website.','<h2>Terms of Use</h2><p>Affinova provides product discovery, recommendations and informational content. Product prices, availability, specifications and retailer terms can change, so verify important details on the retailer website before purchasing.</p><p>Affinova does not guarantee the availability, accuracy or suitability of third-party products or services. Your purchase relationship is with the retailer or marketplace that completes the transaction.</p>','Terms of Use | Affinova','Terms governing use of the Affinova product discovery website.',true,now()),
('affiliate-disclosure','Affiliate Disclosure','How affiliate links support Affinova.','<h2>Affiliate Disclosure</h2><p>Affinova may use affiliate links. If you click an affiliate link and make a qualifying purchase, Affinova may receive a commission at no additional cost to you.</p><p>Affiliate relationships do not change the price you pay. We aim to present products based on relevance and usefulness rather than inventing reviews, traffic or performance data.</p>','Affiliate Disclosure | Affinova','Learn how affiliate links and commissions work on Affinova.',true,now())
